// ArcadeDbAdminServiceServer is the server API for ArcadeDbAdminService service.
// All implementations must embed UnimplementedArcadeDbAdminServiceServer
// for forward compatibility.
//
// The control plane. Every RPC here reaches the same implementation the HTTP control plane reaches
// (com.arcadedb.server.ServerControlPlane), so the two protocols cannot drift apart on what an
// administrative operation does - see issue #7304.
//
// Authentication is enforced centrally by GrpcAuthInterceptor from the 'credentials' field every
// request carries, before the call reaches a handler. Health and Ready are exempt from it, exactly
// as GET /health and GET /ready are unauthenticated over HTTP, so a container orchestrator can probe
// the node without credentials.
//
// Authorization on top of that is per RPC, and mirrors what the HTTP counterpart of each operation
// requires:
//   - Ping, GetServerInfo, ListDatabases, ExistsDatabase and GetDatabaseInfo need only a valid
//     account, as GET /api/v1/databases and GET /api/v1/server do;
//   - GetProgress needs a valid account that is also granted the database it names, the gate
//     GET /api/v1/progress/{database} applies through checkAuthorizationOnDatabase;
//   - every other RPC needs the server-admin (root) principal, the gate POST /api/v1/server and the
//     /api/v1/server/* routes apply through checkRootUser.
//
// Leader routing: CreateDatabase, DropDatabase, CreateUser, DeleteUser, RestoreBackup,
// RestoreDatabase and ImportDatabase are refused on a follower
// with FAILED_PRECONDITION and the leader's address on the arcadedb-leader-* trailers. That is this
// transport's equivalent of the HTTP handler forwarding those four commands to the leader; gRPC has
// no request proxy, so the caller redirects itself.
type ArcadeDbAdminServiceServer interface {
	Ping(context.Context, *PingRequest) (*PingResponse, error)
	GetServerInfo(context.Context, *GetServerInfoRequest) (*GetServerInfoResponse, error)
	ListDatabases(context.Context, *ListDatabasesRequest) (*ListDatabasesResponse, error)
	ExistsDatabase(context.Context, *ExistsDatabaseRequest) (*ExistsDatabaseResponse, error)
	CreateDatabase(context.Context, *CreateDatabaseRequest) (*CreateDatabaseResponse, error)
	DropDatabase(context.Context, *DropDatabaseRequest) (*DropDatabaseResponse, error)
	OpenDatabase(context.Context, *OpenDatabaseRequest) (*OpenDatabaseResponse, error)
	CloseDatabase(context.Context, *CloseDatabaseRequest) (*CloseDatabaseResponse, error)
	AlignDatabase(context.Context, *AlignDatabaseRequest) (*AlignDatabaseResponse, error)
	GetDatabaseInfo(context.Context, *GetDatabaseInfoRequest) (*GetDatabaseInfoResponse, error)
	GetProgress(context.Context, *GetProgressRequest) (*GetProgressResponse, error)
	CreateUser(context.Context, *CreateUserRequest) (*CreateUserResponse, error)
	UpdateUser(context.Context, *UpdateUserRequest) (*UpdateUserResponse, error)
	DeleteUser(context.Context, *DeleteUserRequest) (*DeleteUserResponse, error)
	ListUsers(context.Context, *ListUsersRequest) (*ListUsersResponse, error)
	// groups - the per-database permission documents users hold through the 'databases' map above
	ListGroups(context.Context, *ListGroupsRequest) (*ListGroupsResponse, error)
	SaveGroup(context.Context, *SaveGroupRequest) (*SaveGroupResponse, error)
	DeleteGroup(context.Context, *DeleteGroupRequest) (*DeleteGroupResponse, error)
	// API tokens. CreateApiToken returns secret material and is gated on transport security; see the
	// comment on CreateApiTokenResponse.
	ListApiTokens(context.Context, *ListApiTokensRequest) (*ListApiTokensResponse, error)
	CreateApiToken(context.Context, *CreateApiTokenRequest) (*CreateApiTokenResponse, error)
	DeleteApiToken(context.Context, *DeleteApiTokenRequest) (*DeleteApiTokenResponse, error)
	// settings
	SetServerSetting(context.Context, *SetServerSettingRequest) (*SetServerSettingResponse, error)
	SetDatabaseSetting(context.Context, *SetDatabaseSettingRequest) (*SetDatabaseSettingResponse, error)
	// backup
	GetBackupConfig(context.Context, *GetBackupConfigRequest) (*GetBackupConfigResponse, error)
	SetBackupConfig(context.Context, *SetBackupConfigRequest) (*SetBackupConfigResponse, error)
	ListBackups(context.Context, *ListBackupsRequest) (*ListBackupsResponse, error)
	TriggerBackup(context.Context, *TriggerBackupRequest) (*TriggerBackupResponse, error)
	DeleteBackup(context.Context, *DeleteBackupRequest) (*DeleteBackupResponse, error)
	// query profiler
	ProfilerStart(context.Context, *ProfilerStartRequest) (*ProfilerStateResponse, error)
	ProfilerStop(context.Context, *ProfilerStopRequest) (*ProfilerDocumentResponse, error)
	ProfilerReset(context.Context, *ProfilerResetRequest) (*ProfilerStateResponse, error)
	ProfilerResults(context.Context, *ProfilerResultsRequest) (*ProfilerDocumentResponse, error)
	ProfilerList(context.Context, *ProfilerListRequest) (*ProfilerListResponse, error)
	ProfilerLoad(context.Context, *ProfilerLoadRequest) (*ProfilerDocumentResponse, error)
	// restore and import - server-streaming, see the RestoreProgress section below
	RestoreBackup(*RestoreBackupRequest, grpc.ServerStreamingServer[RestoreProgress]) error
	RestoreDatabase(*RestoreDatabaseRequest, grpc.ServerStreamingServer[RestoreProgress]) error
	ImportDatabase(*ImportDatabaseRequest, grpc.ServerStreamingServer[ImportProgress]) error
	// server lifecycle and cluster
	GetServerEvents(context.Context, *GetServerEventsRequest) (*GetServerEventsResponse, error)
	Shutdown(context.Context, *ShutdownRequest) (*ShutdownResponse, error)
	DisconnectCluster(context.Context, *DisconnectClusterRequest) (*DisconnectClusterResponse, error)
	// The other half of the cluster pair (issue #7400). A thin adapter over the same
	// ServerControlPlane.connectCluster the HTTP `connect cluster` verb calls, so the two transports
	// cannot answer the verb differently. Issue #7401 made that shared method join the named server to
	// the cluster instead of refusing unconditionally; a server whose HA implementation cannot change
	// membership at runtime, or that is not running HA at all, still answers FAILED_PRECONDITION.
	ConnectCluster(context.Context, *ConnectClusterRequest) (*ConnectClusterResponse, error)
	// The operator's override of issue #9449, the RPC twin of POST /api/v1/cluster/accept-diverged/{database}:
	// lifts the quarantine (and its read floor) standing on one database of a node that is the only voter of
	// its cluster, or whose every voter holds the same database quarantined (issue #9553), accepting its copy
	// as it is WITHOUT a resync. Root only. NOT_FOUND when nothing stands on the database, FAILED_PRECONDITION
	// on a node a peer could still resync (a resync from a peer is the way out there) or without HA,
	// INVALID_ARGUMENT on a malformed database name.
	AcceptDivergedDatabase(context.Context, *AcceptDivergedDatabaseRequest) (*AcceptDivergedDatabaseResponse, error)
	// The operator's override of issue #9498, the RPC twin of POST /api/v1/cluster/accept-stale-snapshot: lifts the
	// node-wide stale-snapshot read floor (issue #6111) of a node that is the only voter of its cluster, accepting its
	// databases as they are WITHOUT a resync. Root only. NOT_FOUND when no floor stands, FAILED_PRECONDITION on a node a
	// peer could still resync, while a snapshot download is running, or without HA.
	AcceptStaleSnapshot(context.Context, *AcceptStaleSnapshotRequest) (*AcceptStaleSnapshotResponse, error)
	// Read-only administrative view of the server's open HTTP authentication sessions. gRPC has no
	// session of its own - every admin RPC authenticates from the credentials on the request body - so
	// there is no Login/Logout to go with it (issue #7310).
	ListSessions(context.Context, *ListSessionsRequest) (*ListSessionsResponse, error)
	// probes - unauthenticated, see the service comment
	Health(context.Context, *HealthRequest) (*HealthResponse, error)
	Ready(context.Context, *ReadyRequest) (*ReadyResponse, error)
	mustEmbedUnimplementedArcadeDbAdminServiceServer()
}

